//! Generator for Darkmatter's shipped artifact,
//! `darkmatter/lib/generated/shipped.json`: the prepared catalog, baseline,
//! named types, kind definitions, and function catalogs the library loads
//! instead of preparing their YAML text.
//!
//! - no flag: accepts freshly generated bytes as an artifact over the fresh
//!   Simplified Schema artifact of the same generation, then prints them to
//!   stdout (the root `just shipped-schemas` coordinator reads this); with
//!   `--lower simplified-schema=<path>`, the file at `<path>` must also equal
//!   that fresh lower artifact. A refusal exits 1 and prints nothing. The
//!   compiled-in lower artifact is not consulted.
//! - `--check`: fails when the checked-in artifact (or `--artifact <path>`)
//!   is refused or differs from fresh generation
//! - `--write`: replaces the checked-in artifact with fresh generation
//!
//! `--check` and `--write` first require the compiled-in Simplified Schema
//! artifact to equal its fresh generation, and otherwise name the root
//! `just shipped-schemas`, which regenerates both in order. Generation reads
//! only the compiled-in text, never a checked-in artifact, so it runs even
//! when either artifact is malformed or stale. Errors go to stderr; stdout
//! carries only artifact bytes. The library's L1 suite compiles this file as
//! a module and drives [`run`] in-process.
//!
//! ```text
//! cargo run -p darkmatter --example shipped_schemas -- --check
//! ```

use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use darkmatter::markdown::schemas::shipped::{self as artifact, FreshDarkmatter};
use simplified_schema::shipped::{self as mechanism, DependencyFingerprint, FreshLower, LowerArtifact, registry as lower};

#[allow(dead_code)]
fn main() -> ExitCode {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("generated/shipped.json");
    let code = run(
        std::env::args().skip(1),
        &path,
        lower::ARTIFACT,
        generate,
        &mut std::io::stdout().lock(),
        &mut std::io::stderr().lock(),
    );
    ExitCode::from(code)
}

/// One generation: the fresh Simplified Schema artifact and Darkmatter's
/// artifact prepared over it.
pub struct Generated {
    pub lower: Vec<u8>,
    pub artifact: Vec<u8>,
}

/// Generates both artifacts from current text, uncached.
pub fn generate() -> Result<Generated, String> {
    let fresh_lower = FreshLower::prepare()?;
    let fresh = FreshDarkmatter::prepare(&fresh_lower)?;
    Ok(Generated { lower: fresh_lower.artifact().to_vec(), artifact: fresh.artifact().to_vec() })
}

enum Mode {
    Emit,
    Check,
    Write,
}

const USAGE: &str = "usage: shipped_schemas [--lower <owner>=<path>]... | shipped_schemas (--check [--artifact <path>] | --write)";

struct Arguments {
    mode: Mode,
    /// `--artifact`: the file `--check` reads instead of the checked-in one.
    supplied: Option<PathBuf>,
    /// `--lower simplified-schema=<path>`: the lower candidate emitted bytes
    /// must be built over.
    lower_candidate: Option<PathBuf>,
}

/// Runs the generator over `arguments`: `0` on success, `1` on a refused,
/// stale, or failed generation, `2` on a usage error. `path` is the
/// checked-in file `--check` reads by default and `--write` replaces;
/// `compiled_lower` is the Simplified Schema artifact this build embeds.
pub fn run(
    arguments: impl IntoIterator<Item = String>,
    path: &Path,
    compiled_lower: &[u8],
    generate: impl FnOnce() -> Result<Generated, String>,
    stdout: &mut dyn Write,
    stderr: &mut dyn Write,
) -> u8 {
    let Arguments { mode, supplied, lower_candidate } = match parse_arguments(arguments.into_iter()) {
        Ok(parsed) => parsed,
        Err(message) => {
            let _ = writeln!(stderr, "error: {message}\n{USAGE}");
            return 2;
        }
    };
    let generated = match generate() {
        Ok(generated) => generated,
        Err(message) => {
            let _ = writeln!(stderr, "error: generating `{}` failed: {message}", artifact::ARTIFACT_PATH);
            return 1;
        }
    };
    if !matches!(mode, Mode::Emit) && generated.lower != compiled_lower {
        let _ = writeln!(
            stderr,
            "error: the compiled-in `{}` is stale, so `{}` cannot be checked or written over it; regenerate every artifact with `{}` from the repository root",
            lower::ARTIFACT_PATH,
            artifact::ARTIFACT_PATH,
            artifact::REGENERATE_COMMAND
        );
        return 1;
    }
    match mode {
        Mode::Emit => {
            if let Err(message) = accept_candidate(&generated, lower_candidate.as_deref()) {
                let _ = writeln!(stderr, "error: {message}");
                return 1;
            }
            match stdout.write_all(&generated.artifact).and_then(|()| stdout.flush()) {
                Ok(()) => 0,
                Err(error) => {
                    let _ = writeln!(stderr, "error: cannot write to stdout: {error}");
                    1
                }
            }
        }
        Mode::Check => check(supplied.as_deref().unwrap_or(path), &generated.artifact, stderr),
        Mode::Write => write(path, &generated.artifact, stderr),
    }
}

fn parse_arguments(arguments: impl Iterator<Item = String>) -> Result<Arguments, String> {
    let mut mode = Mode::Emit;
    let mut supplied = None;
    let mut lower_candidate = None;
    let mut arguments = arguments;
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--check" | "--write" if !matches!(mode, Mode::Emit) => {
                return Err("`--check` and `--write` are mutually exclusive".into());
            }
            "--check" => mode = Mode::Check,
            "--write" => mode = Mode::Write,
            "--artifact" => supplied = Some(PathBuf::from(arguments.next().ok_or("`--artifact` needs a path")?)),
            "--lower" => {
                let value = arguments.next().ok_or("`--lower` needs `<owner>=<path>`")?;
                match value.split_once('=') {
                    Some((owner, path)) if owner == lower::OWNER && !path.is_empty() => {
                        if lower_candidate.replace(PathBuf::from(path)).is_some() {
                            return Err(format!("`--lower {owner}=…` is given twice"));
                        }
                    }
                    _ => return Err(format!("`--lower` takes `{}=<path>`, not `{value}`", lower::OWNER)),
                }
            }
            other => return Err(format!("unexpected argument `{other}`")),
        }
    }
    if supplied.is_some() && !matches!(mode, Mode::Check) {
        return Err("`--artifact` applies only to `--check`".into());
    }
    if lower_candidate.is_some() && !matches!(mode, Mode::Emit) {
        return Err("`--lower` applies only when emitting".into());
    }
    Ok(Arguments { mode, supplied, lower_candidate })
}

/// Accepts the generated artifact over the fresh lower artifact it was
/// prepared over, after requiring `lower_candidate` (the lower bytes a
/// caller will publish beside it) to be that same lower artifact.
fn accept_candidate(generated: &Generated, lower_candidate: Option<&Path>) -> Result<(), String> {
    if let Some(path) = lower_candidate {
        let candidate = std::fs::read(path).map_err(|error| format!("cannot read `{}`: {error}", path.display()))?;
        if candidate != generated.lower {
            return Err(format!(
                "`{}` is not the `{}` artifact this generation of `{}` is built over",
                path.display(),
                lower::OWNER,
                artifact::ARTIFACT_PATH
            ));
        }
    }
    let lower = LowerArtifact::Current(DependencyFingerprint::of_bytes(lower::OWNER, lower::PREPARATION_REVISION, &generated.lower));
    artifact::Registry::load_over(Some(&generated.artifact), lower)
        .check_all()
        .map_err(|refusal| format!("freshly generated `{}` is refused: {refusal}", artifact::ARTIFACT_PATH))
}

fn check(path: &Path, fresh: &[u8], stderr: &mut dyn Write) -> u8 {
    let checked_in = match std::fs::read(path) {
        Ok(bytes) => bytes,
        Err(error) => {
            let _ = writeln!(stderr, "error: cannot read `{}`: {error}", path.display());
            return 1;
        }
    };
    if let Err(refusal) = artifact::check_artifact(&checked_in) {
        let _ = writeln!(
            stderr,
            "error: `{}` is refused: {refusal}\nregenerate it with `{}`",
            path.display(),
            artifact::REGENERATE_COMMAND
        );
        return 1;
    }
    match mechanism::check_fresh(&checked_in, fresh, artifact::ARTIFACT_PATH, artifact::REGENERATE_COMMAND) {
        Ok(()) => 0,
        Err(stale) => {
            let _ = writeln!(stderr, "error: {stale}");
            1
        }
    }
}

/// Validates `fresh` as an artifact before replacing `path` through a
/// sibling temporary file, so a failure leaves the old file in place.
fn write(path: &Path, fresh: &[u8], stderr: &mut dyn Write) -> u8 {
    if let Err(refusal) = artifact::check_artifact(fresh) {
        let _ = writeln!(stderr, "error: freshly generated bytes are refused: {refusal}");
        return 1;
    }
    if std::fs::read(path).is_ok_and(|current| current == fresh) {
        return 0;
    }
    let temporary = path.with_extension("json.tmp");
    if let Err(error) = std::fs::write(&temporary, fresh).and_then(|()| std::fs::rename(&temporary, path)) {
        let _ = std::fs::remove_file(&temporary);
        let _ = writeln!(stderr, "error: cannot write `{}`: {error}", path.display());
        return 1;
    }
    0
}
